\begin{equation}\label{eq:prob}
    \min_{x\in\R^n}~f(x),
\end{equation}

\begin{ass}[Basic assumptions]\label{ass:basic} For problem \eqref{eq:prob}, we assume:
\begin{description}
\item[(a)] The function $\func{f}{\R^n}{\R}$ is continuously differentiable, i.e., $f\in\C^1$, and possibly nonconvex;
\item[(b)] The set of minimizers $\mathcal{X}^*:=\argmin_{x\in \R^n} f(x)$ is nonempty, with $f^*$ denoting the optimal value.
\end{description}
\end{ass}

In this paper, $\R^n$ denotes the $n$-dimensional real \textit{Euclidean space} equipped with the standard \textit{inner product} $\innprod{\cdot}{\cdot}$ and the associated \textit{Euclidean norm} $\|\cdot\|=\sqrt{\innprod{\cdot}{\cdot}}$.
The notation $\N$ stands for the set of \textit{natural numbers}, and $\N_{0}:=\N\cup \{0\}$.
The \textit{open ball} of radius $r>0$ centered at $x\in\R^n$ is denoted by $B(x;r)$.
The \textit{interior} of a set $S\subseteq\R^n$ is denoted by $\interior\, S$.
The \textit{Euclidean distance} from a point $x\in\R^n$ to a nonempty set $S\subseteq\R^n$ is given by $\dist(x;S)=\inf_{z\in S} \|z-x\|$.
The \textit{ceiling function}, denoted by $\lceil x \rceil$, assigns to each real number $x$ the smallest integer greater than or equal to it.
A point $\ov{x}$ is called a \textit{cluster point} of a sequence $\{x^k\}_{k \in \N_0}$ if there exists a subsequence converging to $\ov{x}$.


For a function $h: \R^n \to \Rinf:=\R\cup\{+\infty\}$, the \textit{effective domain} is defined as 
$\dom{(h)}:= \{x \in   \R^{n}\mid~h(x)< + \infty \}$,
and $h$ is called \textit{proper} if $\dom(h)\neq \emptyset$.
%%%%%%%%%%%%%%%%%%%%%%%%%%
A function $h$ is \textit{lower semicontinuous} (lsc) at $\ov{x} \in \R^n$ if, for any sequence 
$\{x^k\}_{k\in \mathbb{N}} \subseteq \R^n$ with $x^k \to \ov{x}$, it follows that
$\liminf_{k \to +\infty} h(x^k) \geq h(\ov{x})$.

A proper function $h: \R^n \to \Rinf$ is said to be \textit{Fr\'{e}chet differentiable} at $\ov{x}\in \idom(h)$ with \textit{Fr\'{e}chet derivative} $\nabla h(\ov{x})$ if
\[
\lim_{x\to \ov{x}}\tfrac{h(x) -h(\ov{x}) - \langle \nabla h(\ov{x}) , x - \ov{x}\rangle}{\Vert x - \ov{x}\Vert}=0.
\]
The point $\ov{x}\in \idom(h)$ is called a \textit{critical point} of $h$ if $\nabla h(\ov x)=0$.


The \textit{Fr\'{e}chet/regular} and \textit{Mordukhovich/limiting subdifferentials} of $h$ at $\ov{x}\in \dom{(h)}$ \cite{Mordukhovich2018,rockafellar2011variational} are defined, respectively, as
\[
\widehat{\partial}h(\ov{x}):=\left\{\zeta\in \R^n\mid~\liminf_{x\to \ov{x}}\tfrac{h(x)- h(\ov{x}) - \langle \zeta, x - \ov{x}\rangle}{\Vert x - \ov{x}\Vert}\geq 0\right\},
\]
and
\[
\partial h(\ov{x}):=\left\{\zeta\in \R^n\mid~\exists x^k\to \ov{x}, \zeta^k\in \widehat{\partial}h(x^k),~~\text{with}~~h(x^k)\to h(\ov{x})~\text{and}~ \zeta^k\to \zeta\right\}.
\]
If $\func{h}{\R^n}{\R}$ is continuously differentiable, i.e., $h\in \C^1$, then
$\partial h(\ov{x})=\{\nabla h(\ov{x})\}$ \cite[page 20]{Mordukhovich2018}.


\begin{defin}[\textbf{Kurdyka-{\L}ojasiewicz inequality}] \label{def:LojaIneqDef}
    Let $\func{h}{\R^n}{\R}$ be a lsc function.
    \begin{enumerate}
        \item\label{def:LojaIneqDef-l}
             We say that $h$ satisfies the \textit{Kurdyka-{\L}ojasiewicz} (KL) inequality at $\ov x \in \R^n$ if there exist constants $r, \xi, \tau>0$ and an exponent $\vartheta \in (0,1)$ such that
            \begin{equation}\label{eq:LojaIneqGrad}
                \big(h(x)-h(\ov x)\big)^\vartheta\leq \tau~\dist(0;\partial h(x)),
            \end{equation}
            whenever $x\in B(\ov x;r)$ and $h(\ov x)<h(x) <h(\ov x)+\xi$.
        \item\label{def:LojaIneqDef-g}
             Let $h^*:=\inf_{x\in \R^n} h(x)>-\infty$. The function $h$ is said to satisfy the \textit{global Kurdyka-{\L}ojasiewicz (global KL) inequality} if there exist constants $\tau>0$ and an exponent $\vartheta \in (0,1)$ such that
             \begin{equation}\label{eq:LojaIneqGrad:g}
                \big(h(x)-h^*\big)^\vartheta\leq \tau~\dist(0;\partial h(x)),\quad\forall x\in \R^n.
            \end{equation}
    \end{enumerate}
    The function $h$ is said to be a \textit{KL function} at $\ov{x}$ if it satisfies the KL inequality at $\ov{x}$.
Moreover, $h$ is called a \textit{global KL function} if it satisfies the global KL inequality.
\end{defin}

In this paper, we use the (global) KL inequality to unify the convergence analysis of generalized descent methods. For $h\in \mathcal{C}^1$, we have 
\[
\dist(0;\partial h(x))=\Vert\nabla h(x)\Vert,
\]


\begin{algorithm}
\DontPrintSemicolon
\textbf{Initialization:} $x^0\in\R^n$,~$\rho>0$,~$\theta>1$,~ $k=0$;

    \Repeat{the stopping criteria holds
    }{
    Generate $x^{k+1}$ satisfying
    \begin{equation}\label{eq:deal}
    f(x^{k+1})\leq f(x^{k})-\rho\Vert \nabla f(x^{k})\Vert^{\theta};
    \end{equation}
    \\Set $k=k+1$;
    }
\caption{DEAL (Generalized DEscent ALgorithm) \label{alg:deal}}
\end{algorithm}

\begin{ass}[Convergent subsequence]\label{ass:bo}
The sequence $\seq{x^k}$ generated by Algorithm \ref{alg:deal} has a convergent subsequence.
\end{ass}

