\begin{thm}[Linear convergence rate of DEAL] 
\label{thm:LinConvWeakDeal-s}
     Let the sequence $\seq{x^k}$ be generated by Algorithm~\ref{alg:deal} under Assumption~\ref{ass:bo}. Let us assume that there exists $c>0$ such that 
     \[\Vert x^{k+1}-x^k\Vert \leq c\Vert \nabla f(x^k)\Vert^{\theta-1},\]
     for all sufficiently large $k\in\N$. If $\ov x$ is a cluster point at which the KL inequality holds with exponent $\vartheta$ and constant $\tau>0$, then the following assertions hold:
    \begin{enumerate}
        \item\label{thm:LinConvWeakDealFun-s:0}
            If $\theta<\tfrac{1}{\vartheta}$, the sequences $\seq{f(x^k)-f(\ov x)}$, $\seq{\|\nabla f(x^k)\|}$, and $\seq{\|x^k-\ov x\|}$ become zero in finitely many iterations;
        \item\label{thm:LinConvWeakDealFun-s:1}
            If $\theta=\tfrac{1}{\vartheta}$, the sequences $\seq{f(x^k)-f(\ov x)}$, $\seq{\|\nabla f(x^k)\|}$, and $\seq{\|x^k-\ov x\|}$ converge linearly to $0$, i.e.,
        \begin{equation}\label{eq:convRateFun-s}
            f(x^{k+1})-f(\ov x)\leq q (f(x^k)-f(\ov x)),
        \end{equation}
        \begin{equation}\label{eq:LinIneqNablaDeal-s}
            \|\nabla f(x^k)\|\le \Big( \tfrac{f(x^0)-f(\ov x)}{\rho}\Big)^{\tfrac{1}{\theta}} q^{\tfrac{k}{\theta}},
        \end{equation}
        \begin{equation}\label{eq:LinIneqIteDealp-s}
        \|x^k-\ov x\| \le \tfrac{c}{1-q^{\tfrac{\theta-1}{\theta}}}\Big( \tfrac{f(x^0)-f(\ov x)}{\rho}\Big)^{\tfrac{\theta-1}{\theta}} q^{\tfrac{k(\theta-1)}{\theta}},
        \end{equation}
        as $k\to \infty$, where $q:= 1- \tfrac{\rho}{\tau^{\theta}}\in (0, 1)$;
        \item\label{thm:LinConvWeakDealFun-s:2}
            If $\theta>\tfrac{1}{\vartheta}$, there exists $\mu>0$ such that 
            \begin{equation}\label{eq:convRateFun2-s}
                0\leq f(x^k)-f(\ov x)\leq \mu k^{-\tfrac{1}{\vartheta \theta-1}},
            \end{equation}
            \begin{equation}\label{eq:SubLinIneqNablaDeal-s}
            \|\nabla f(x^k)\|\leq \big(\tfrac{\mu}{\rho}\big)^{\tfrac{1}{\theta}} k^{-\tfrac{1}{\theta(\vartheta \theta-1)}},
            \end{equation}
            \begin{equation}\label{eq:SubLinIneqItarDeal-s}
            \|x^k-\ov x\|\leq c  \tau\rho^{-1}(1-\vartheta)^{-1}\mu^{1-\vartheta} k^{-\tfrac{1-\vartheta}{\vartheta \theta-1}},
            \end{equation}
           for all sufficiently large $k\in\N_{0}$.
    \end{enumerate}
\end{thm}

