\begin{fact}[\textbf{Convergence of a sequence with positive elements}]\cite[Lemma 1]{aragon2018accelerating}
\label{lem:convRate1} 
    Let $\seq{s^k}$ be a sequence in $(0, +\infty)$ converging to $0$, and let $\varsigma\ge 1$ and $\omega>0$. Suppose that for some $k_0\in \N_0$,
    \begin{equation}\label{eq:sk}
        (s^k)^{\varsigma}\leq\omega(s^k-s^{k+1}),\quad\forall k\ge k_0.
    \end{equation}
    Then the following assertions hold:
    \begin{description}
        \item[(a)] If $\varsigma=1$, then necessarily $\omega>1$, and the sequence $\seq{s^k}$ converges linearly to $0$ with rate $1-\tfrac{1}{\omega}$, i.e.,
        \begin{equation}\label{eq:sk1}
        s^{k+1} \le \big(1-\tfrac{1}{\omega}\big) s^{k}, \quad \forall k\ge k_0;
        \end{equation}
        \item[(b)] If $\varsigma>1$, then there exists a constant $\mu>0$ such that 
        \[
            0\leq s^k\leq \mu k^{-\tfrac{1}{\varsigma-1}},
        \]
        for all sufficiently large $k\in\N_{0}$.
    \end{description}
\end{fact}

\begin{rem}\label{rem:lem:convRate1}
    In \cite[Lemma 1]{aragon2018accelerating}, the condition \eqref{eq:sk} is assumed to hold for all sufficiently large $k$. Since we are using a special case of that lemma, it suffices to require \eqref{eq:sk} only for all $k\geq k_0$ for some $k_0\in \N_0$. In fact, inequality \eqref{eq:sk1} is obtained directly by setting $\varsigma=1$ in \eqref{eq:sk}. Moreover, since $s^{k+1}>0$, the inequality \eqref{eq:sk1} immediately implies that $\omega>1$.\qed
\end{rem}


\begin{thm}[Global convergence of DEAL] \label{thm:GlobConv-s}
Let the sequence $\seq{x^k}$ be generated by Algorithm \ref{alg:deal}. The following assertions hold:
    \begin{enumerate}
        \item\label{thm:GlobConv-s:1} 
            The sequence of function values $\seq{f(x^k)}$ is non-increasing;
        \item\label{thm:GlobConv-s:2}
            We have $\sum_{k=0}^\infty\Vert \nabla f(x^k)\Vert^{\theta}< \infty$ and $\displaystyle\lim_{k\to\infty} \|\nabla f(x^k)\|=0$;
        %, and $\displaystyle\lim_{k\to\infty} f(x^k)=f^*$;
        \item\label{thm:GlobConv-s:3}
            If Assumption~\ref{ass:bo} holds, every cluster point $\ov x$ of $\seq{x^k}$ is a critical point, and $\displaystyle \lim_{k\to\infty}f(x^k)= f(\ov x)$;
        \item\label{thm:GlobConv-s:4}
             If Assumption~\ref{ass:bo} holds, and there exists $c>0$ such that
            \[\|x^{k+1} - x^k\| \leq c \|\nabla f(x^k)\|^{\theta - 1},\]
            for all sufficiently large $k \in \N_{0}$, 
            and if the KL inequality holds at a cluster point $\ov{x}$ of $\seq{x^k}$, then $x^k\to \ov x$.
    \end{enumerate}
\end{thm}

\begin{proof}
Assertion~\ref{thm:GlobConv-s:1} follows directly from \eqref{eq:deal} and $\rho>0$.
   For Assertion~\ref{thm:GlobConv-s:2}, summing both sides of \eqref{eq:deal} from $k=0$ to $k=N$ yields
   \begin{equation}\label{eq:thm:GlobConv-s}
       \rho\sum_{k=0}^N\Vert \nabla f(x^k)\Vert^{\theta}\leq f(x^0)-f(x^{N+1})\le f(x^0)- f^*,
   \end{equation}
    which implies $\sum_{k=0}^\infty\Vert \nabla f(x^k)\Vert^{\theta}< \infty$ and $\displaystyle\lim_{k\to\infty} \|\nabla f(x^k)\|=0$, verifying the desired result.
For Assertion~\ref{thm:GlobConv-s:3}, let a subsequence $\subseq{x^{k_j}}$ converge to $\ov{x}$. 
Since $f\in \mathcal{C}^1$, the gradient is continuous, and thus $\nabla f(x^{k_j})\to \nabla f(\ov x)$.
Hence, by Assertion~\ref{thm:GlobConv-s:2}, $\|\nabla f(\ov x)\|=0$ and $\ov x$ is a critical point.  
Since $\seq{f(x^k)}$ is non-increasing and bounded below, it converges, and therefore $f(x^k)\to f(\ov x)$.  

Finally, for Assertion~\ref{thm:GlobConv-s:4}, let $\ov x$ be a cluster point where the KL inequality holds. 
Let $r,\xi,\tau>0$ be the constants associated with the KL inequality at $\ov x$ (cf. Definition~\ref{def:LojaIneqDef}). 
If $\nabla f(x^k)=0$ for some $k$, the result is trivial; otherwise, assume $\nabla f(x^k)\neq 0$ for all $k$.  
Since $\ov x$ is a cluster point, Assertion~\ref{thm:GlobConv-s:3} yields that $f(x^k)\to f(\ov x)$. Moreover, there exists $\ov k$ such that $x^{\ov k}\in\Gamma$, where
\[
\Gamma := \{x\in B(\ov x;r) : f(\ov x)< f(x)< f(\ov x)+\xi\}.
\]
Additionally, as $\|x^{k+1}-x^k\|\to 0$, we have $x^k\in\Gamma$ for all $k\geq \ov k$, possibly enlarging $\ov k$.  
Define $\Delta_k:=\left(f(x^k)-f(\ov x)\right)^{1-\vartheta}$ for $k\ge \ov k$.
By concavity of $\phi(t)=t^{1-\vartheta}$ on $(0, +\infty)$, together with \eqref{eq:deal} and the KL inequality, we obtain 
 \begin{align}\label{eq:th:conKL:z1-s}
  \Delta_{k}-\Delta_{k+1} \geq 
  (1-\vartheta)\left(f(x^{k})-f(\ov x)\right)^{-\vartheta}
\left[f(x^{k})-f(x^{k +1})\right]\geq 
  \tau^{-1}\rho (1-\vartheta)
\Vert\nabla f(x^{k})\Vert^{\theta-1},
\end{align}
i.e.,
\[
\Delta_{k}-\Delta_{k+1} \geq c^{-1}\tau^{-1}\rho (1-\vartheta) \|x^{k+1}-x^{k}\|.
\]
Summing both sides of this inequality over $k$ yields
\begin{align*}
\sum_{k=0}^{\infty}\Vert x^{k+1}-x^k\Vert
&\leq \sum_{k=0}^{\ov k -1}\Vert x^{k+1}-x^k\Vert + \sum_{k=\ov k}^{\infty}\Vert x^{k+1}-x^k\Vert
\le \sum_{k=0}^{\ov k -1}\Vert x^{k+1}-x^k\Vert+\tfrac{c\tau}{\rho(1-\vartheta)}\sum_{k=\ov k}^{\infty}\left(\Delta_k-\Delta_{k+1} \right)\\
&=\sum_{k=0}^{\ov k -1}\Vert x^{k+1}-x^k\Vert+\tfrac{c\tau}{\rho(1-\vartheta)}\Delta_{\ov k}<\infty.
\end{align*}
Thus, $\{x^k\}_{k\in \N_0}$ is a Cauchy sequence and therefore converges to $\ov x$.
    \qed
\end{proof}

\begin{proof}
By Theorem~\ref{thm:GlobConv-s}~\ref{thm:GlobConv-s:4}, $x^k\to \ov x$ and $f(x^k)\to f(\ov x)$.
From the KL inequality, there exists $k_0\in \N$ such that
\[
\big(f(x^{k}) -f(\ov x)\big)^{\vartheta}\le \tau \|\nabla f(x^k)\|, \quad\quad \forall k\ge k_0.
\]
Combining this with \eqref{eq:deal} gives
    \begin{equation}\label{eq:decIneqCSS1}
        \tfrac{\rho}{\tau^{\theta}} \big(f(x^{k}) -f(\ov x)\big)^{\vartheta\theta}\le \rho \|\nabla f(x^k)\|^{\theta} \le f(x^{k}) - f(x^{k+1}) = \big(f(x^{k}) -f(\ov x)\big) - \big(f(x^{k+1})-f(\ov x)\big),
    \end{equation}
    for all $k\ge k_0$.\\
    \ref{thm:LinConvWeakDealFun-s:0} By indirect proof, assume that $x^{k+1}\neq x^k$ for all $k\in \N_0$. It follows from \eqref{eq:decIneqCSS1} that
    \[
     \big(f(x^k)-f(\ov x)\big)^{1-\vartheta \theta}\geq \tfrac{\rho}{\tau^\theta}>0,
     \quad\quad \forall k\ge k_0,
    \]
    making a contradiction with $f(x^k)\to f(\ov x)$. Thus, all three sequences reach zero in a finite number of iterations.\\
    \ref{thm:LinConvWeakDealFun-s:1}-\ref{thm:LinConvWeakDealFun-s:2} Considering \eqref{eq:decIneqCSS1} and setting $s^k:=f(x^k)-f(\ov x)$, $\varsigma=\vartheta\theta$, and $\omega:= \tfrac{\tau^{\theta}}{\rho}$, we obtain a recurrence of the form \eqref{eq:sk}. 
    Applying Fact~\ref{lem:convRate1} and Remark~\ref{rem:lem:convRate1} yields $\omega >1$, $q\in (0,1)$, and the rates in \eqref{eq:convRateFun-s} and \eqref{eq:convRateFun2-s}.  Moreover, from \eqref{eq:deal}, 
    \begin{equation*}
        \rho \|\nabla f(x^k)\|^\theta \le f(x^{k})-f(x^{k+1}) \le f(x^k) -f(\ov x),
    \end{equation*}
   which, together with \eqref{eq:convRateFun-s} and \eqref{eq:convRateFun2-s}, implies \eqref{eq:LinIneqNablaDeal-s} and \eqref{eq:SubLinIneqNablaDeal-s}. To prove \eqref{eq:LinIneqIteDealp-s}, using 
    $\Vert x^{k+1}-x^k\Vert \leq c\Vert \nabla f(x^k)\Vert^{\theta-1}$ and \eqref{eq:LinIneqNablaDeal-s}, we obtain
    \begin{align*}
        \|x^k - \ov x\| &\le \sum_{i\ge k} \|x^i -x^{i+1}\|\le \sum_{i\ge k} c\|\nabla f(x^i)\|^{\theta-1}
        \le c\Big( \tfrac{f(x^0)-f(\ov x)}{\rho}\Big)^{\tfrac{\theta-1}{\theta}} \sum_{i\ge k}   q^{\tfrac{i(\theta -1)}{\theta}}
        = c\Big( \tfrac{f(x^0)-f(\ov x)}{\rho}\Big)^{\tfrac{\theta-1}{\theta}}  \tfrac{q^{\tfrac{k(\theta-1)}{\theta}}}{1-q^{\tfrac{\theta -1}{\theta}}},
    \end{align*}
    for all $k\ge k_0$.
Let us set $\theta>\tfrac{1}{\vartheta}$. 
Arguing as in the proof of Theorem~\ref{thm:GlobConv-s}~\ref{thm:GlobConv-s:4} (see in particular the derivation of
\eqref{eq:th:conKL:z1-s}), we obtain
\begin{equation}\label{eq:thm:LinConvWeakDealFun-s:1:a}
    \Delta_{k}-\Delta_{k+1} \geq \tau^{-1}\rho (1-\vartheta)\Vert\nabla f(x^{k})\Vert^{\theta-1},
\end{equation}
where $\Delta_k:=\left(f(x^k)-f(\ov x)\right)^{1-\vartheta}$. 
Moreover, by \eqref{eq:convRateFun2-s}, there exists a constant $\mu>0$ such that, for all
sufficiently large $k\in\N_{0}$,
\[
\Delta_k\leq \mu^{1-\vartheta} k^{-\tfrac{1-\vartheta}{\vartheta \theta-1}}.
\]
Together with \eqref{eq:thm:LinConvWeakDealFun-s:1:a}, this estimate yields, for all sufficiently
large $k\in\N_{0}$,
    \begin{align*}
        \|x^k - \ov x\| \le \sum_{i\ge k} c\|\nabla f(x^i)\|^{\theta-1} &\le 
