\begin{defin}[\textbf{Kurdyka-{\L}ojasiewicz inequality}] \label{def:LojaIneqDef}
    Let $\func{h}{\R^n}{\R}$ be a lsc function.
    \begin{enumerate}
        \item\label{def:LojaIneqDef-l}
             We say that $h$ satisfies the \textit{Kurdyka-{\L}ojasiewicz} (KL) inequality at $\ov x \in \R^n$ if there exist constants $r, \xi, \tau>0$ and an exponent $\vartheta \in (0,1)$ such that
            \begin{equation}\label{eq:LojaIneqGrad}
                \big(h(x)-h(\ov x)\big)^\vartheta\leq \tau~\dist(0;\partial h(x)),
            \end{equation}
            whenever $x\in B(\ov x;r)$ and $h(\ov x)<h(x) <h(\ov x)+\xi$.
        \item\label{def:LojaIneqDef-g}
             Let $h^*:=\inf_{x\in \R^n} h(x)>-\infty$. The function $h$ is said to satisfy the \textit{global Kurdyka-{\L}ojasiewicz (global KL) inequality} if there exist constants $\tau>0$ and an exponent $\vartheta \in (0,1)$ such that
             \begin{equation}\label{eq:LojaIneqGrad:g}
                \big(h(x)-h^*\big)^\vartheta\leq \tau~\dist(0;\partial h(x)),\quad\forall x\in \R^n.
            \end{equation}
    \end{enumerate}
    The function $h$ is said to be a \textit{KL function} at $\ov{x}$ if it satisfies the KL inequality at $\ov{x}$.
Moreover, $h$ is called a \textit{global KL function} if it satisfies the global KL inequality.
\end{defin}

